#include "what_changed/collectors.hpp"
#include "what_changed/diff.hpp"
#include "what_changed/output.hpp"
#include "what_changed/util.hpp"
#include <filesystem>
#include <fstream>
#include <functional>
#include <iostream>
#include <stdexcept>
#include <sys/stat.h>
#include <unistd.h>

namespace fs=std::filesystem;
namespace {struct Tmp{fs::path p;Tmp(){std::string t="/tmp/what-changed-test.XXXXXX";std::vector<char>b(t.begin(),t.end());b.push_back(0);auto*x=mkdtemp(b.data());if(!x)throw std::runtime_error("mkdtemp");p=x;}~Tmp(){std::error_code e;fs::remove_all(p,e);}};
void put(const fs::path&p,const std::string&s){fs::create_directories(p.parent_path());std::ofstream f(p,std::ios::binary);f<<s;if(!f)throw std::runtime_error("fixture write");}
void check(bool x,const std::string&m){if(!x)throw std::runtime_error(m);}
template<class F>void throws(F f){bool ok=false;try{f();}catch(...){ok=true;}check(ok,"expected exception");}
wc::Snapshot one(const std::string&cat,const std::string&status="ok"){wc::Snapshot s;s.captured_at="2026-01-01T00:00:00Z";s.categories[cat].status=status;return s;}
std::size_t open_fd_count(){std::size_t count=0;for(const auto&entry:fs::directory_iterator("/proc/self/fd")){static_cast<void>(entry);++count;}return count;}
void base(const fs::path&r){put(r/"etc/os-release","ID=debian\nVERSION_ID=13\nPRETTY_NAME=Sentinel OS\n");put(r/"var/lib/dpkg/status","Package: alpha\nStatus: install ok installed\nArchitecture: amd64\nVersion: 1.0\n\n");put(r/"usr/lib/systemd/system/demo.service","[Unit]\n");put(r/"proc/self/mountinfo","1 0 8:1 / / rw,relatime - ext4 /dev/sda1 rw\n");}
}
int main(){std::vector<std::pair<std::string,std::function<void()>>>t;
 t.push_back({"json round trip",[]{auto j=wc::Json::parse("{\"a\":[1,true,null,\"x\"]}");check(wc::Json::parse(j.dump()).dump()==j.dump(),"roundtrip");}});
 t.push_back({"json escapes",[]{auto j=wc::Json::parse("\"a\\n\\t\\u263a\"");check(j.is_string()&&j.as_string().size()>3,"escapes");}});
 t.push_back({"duplicate JSON key",[]{throws([]{wc::Json::parse("{\"a\":1,\"a\":2}");});}});
 t.push_back({"truncated JSON",[]{throws([]{wc::Json::parse("{\"a\":");});}});
 t.push_back({"invalid UTF-8",[]{std::string s="\"";s.push_back(static_cast<char>(0xff));s+='"';throws([&]{wc::Json::parse(s);});}});
 t.push_back({"unsupported future schema",[]{auto s=one("x");auto j=wc::snapshot_to_json(s);j.as_object()["schema_version"]=wc::Json(std::int64_t(2));throws([&]{wc::snapshot_from_json(j);});}});
 t.push_back({"invalid schema",[]{auto s=one("x");auto j=wc::snapshot_to_json(s);j.as_object()["schema_version"]=wc::Json(std::int64_t(0));throws([&]{wc::snapshot_from_json(j);});}});
 t.push_back({"unknown schema field",[]{auto s=one("x");auto j=wc::snapshot_to_json(s);j.as_object()["evil"]=wc::Json("x");throws([&]{wc::snapshot_from_json(j);});}});
 t.push_back({"deterministic serialization",[]{auto s=one("packages");s.categories["packages"].entries["z"]=wc::Json("2");s.categories["packages"].entries["a"]=wc::Json("1");check(wc::serialize_snapshot(s)==wc::serialize_snapshot(s),"determinism");check(wc::serialize_snapshot(s).find("\"a\"")<wc::serialize_snapshot(s).find("\"z\""),"order");}});
 t.push_back({"metadata ignored",[]{auto a=one("x"),b=a;b.captured_at="later";check(wc::compare(a,b).changes.empty(),"timestamp diff");}});
 t.push_back({"package install removal",[]{auto a=one("packages"),b=a;a.categories["packages"].entries["old"]=wc::Json::Object{{"version","1"}};b.categories["packages"].entries["new"]=wc::Json::Object{{"version","1"}};auto d=wc::compare(a,b);check(d.changes.size()==2,"add/remove");check(d.changes[0].type=="installed"&&d.changes[1].type=="removed","types/order");}});
 t.push_back({"package upgrade",[]{auto a=one("packages"),b=a;a.categories["packages"].entries["p"]=wc::Json::Object{{"architecture","amd64"},{"version","1.2"}};b.categories["packages"].entries["p"]=wc::Json::Object{{"architecture","amd64"},{"version","1.10"}};check(wc::compare(a,b).changes[0].type=="upgraded","upgrade");check(wc::compare(b,a).changes[0].type=="downgraded","inverse");}});
 t.push_back({"package architecture",[]{auto a=one("packages"),b=a;a.categories["packages"].entries["p"]=wc::Json::Object{{"architecture","amd64"},{"version","1"}};b.categories["packages"].entries["p"]=wc::Json::Object{{"architecture","arm64"},{"version","1"}};check(wc::compare(a,b).changes[0].type=="architecture-changed","arch");}});
 t.push_back({"unavailable not removal",[]{auto a=one("packages"),b=one("packages","unavailable");a.categories["packages"].entries["p"]=wc::Json("x");auto d=wc::compare(a,b);check(d.changes.empty()&&d.unavailable.size()==1,"false removal");}});
 t.push_back({"service enable disable",[]{auto a=one("services"),b=a;a.categories["services"].entries["x.service"]=wc::Json::Object{{"enabled","disabled"},{"state_kind","persistent"}};b.categories["services"].entries["x.service"]=wc::Json::Object{{"enabled","enabled"},{"state_kind","persistent"}};check(wc::compare(a,b).changes[0].type=="enabled","enabled");check(wc::compare(b,a).changes[0].type=="disabled","disabled");}});
 t.push_back({"transient service noise omitted",[]{auto a=one("services"),b=a;a.categories["services"].entries["x"]=wc::Json::Object{{"active","active"},{"state_kind","mixed"}};b.categories["services"].entries["x"]=wc::Json::Object{{"active","inactive"},{"state_kind","mixed"}};check(wc::compare(a,b).changes.empty(),"noise");check(wc::compare(a,b,true).changes.size()==1,"requested transient");}});
 t.push_back({"Debian fixture collector",[]{Tmp x;base(x.p);wc::CaptureOptions o;o.root=x.p;auto s=wc::capture(o);check(s.categories["packages"].entries.count("alpha"),"dpkg");check(s.categories["operating-system"].status=="ok","os");}});
 t.push_back({"Fedora RPM fixture parser",[]{auto c=wc::parse_rpm_query_output("bash\t0:5.2-1.fc42\tx86_64\ncoreutils\t0:9.6-2.fc42\tx86_64\n");check(c.entries.size()==2&&c.entries.at("bash").at("architecture").as_string()=="x86_64","rpm fixture");}});
 t.push_back({"persistent plus transient service",[]{auto a=one("services"),b=a;a.categories["services"].entries["x"]=wc::Json::Object{{"active","active"},{"enabled","disabled"},{"state_kind","mixed"}};b.categories["services"].entries["x"]=wc::Json::Object{{"active","inactive"},{"enabled","enabled"},{"state_kind","mixed"}};auto d=wc::compare(a,b);check(d.changes.size()==1&&d.changes[0].type=="enabled","persistent retained");}});
 t.push_back({"minimal missing collectors",[]{Tmp x;wc::CaptureOptions o;o.root=x.p;auto s=wc::capture(o);check(s.categories["packages"].status=="unavailable","pkg missing");check(s.categories["services"].status=="unavailable","systemd missing");}});
 t.push_back({"configuration changed",[]{Tmp x;base(x.p);put(x.p/"etc/fstab","first");wc::CaptureOptions o;o.root=x.p;auto a=wc::capture(o);put(x.p/"etc/fstab","second");auto b=wc::capture(o);auto d=wc::compare(a,b);bool found=false;for(auto&c:d.changes)if(c.category=="configuration"&&c.key=="/etc/fstab")found=true;check(found,"content change");}});
 t.push_back({"configuration mode changed",[]{Tmp x;base(x.p);put(x.p/"etc/fstab","same");chmod((x.p/"etc/fstab").c_str(),0600);wc::CaptureOptions o;o.root=x.p;auto a=wc::capture(o);chmod((x.p/"etc/fstab").c_str(),0644);auto b=wc::capture(o);check(!wc::compare(a,b).changes.empty(),"mode");}});
 t.push_back({"configuration owner changed",[]{auto a=one("configuration"),b=a;a.categories["configuration"].entries["/etc/x"]=wc::Json::Object{{"state","hashed"},{"uid",std::int64_t(0)}};b.categories["configuration"].entries["/etc/x"]=wc::Json::Object{{"state","hashed"},{"uid",std::int64_t(1000)}};check(wc::compare(a,b).changes.size()==1,"owner");}});
 t.push_back({"configuration disappeared",[]{Tmp x;base(x.p);put(x.p/"etc/fstab","same");wc::CaptureOptions o;o.root=x.p;auto a=wc::capture(o);fs::remove(x.p/"etc/fstab");auto b=wc::capture(o);auto d=wc::compare(a,b);bool found=false;for(const auto&c:d.changes)if(c.key=="/etc/fstab"&&c.type=="modified")found=true;check(found,"disappearance");}});
 t.push_back({"symlink not followed",[]{Tmp x;base(x.p);put(x.p/"secret","TOP_SECRET_SENTINEL");fs::create_directories(x.p/"etc");fs::create_symlink(x.p/"secret",x.p/"etc/fstab");wc::CaptureOptions o;o.root=x.p;auto s=wc::capture(o);auto text=wc::serialize_snapshot(s);check(text.find("symlink-not-followed")!=std::string::npos,"symlink state");check(text.find("TOP_SECRET_SENTINEL")==std::string::npos,"secret followed");}});
 t.push_back({"large config bounded",[]{Tmp x;base(x.p);put(x.p/"etc/fstab",std::string(65U*1024U*1024U,'x'));wc::CaptureOptions o;o.root=x.p;auto s=wc::capture(o);auto&j=s.categories["configuration"].entries["/etc/fstab"];check(j.at("state").as_string()=="too large","large");}});
 t.push_back({"repository credential privacy",[]{Tmp x;base(x.p);put(x.p/"etc/apt/sources.list","deb https://alice:TOPSECRET@example.test/path?token=LEAK stable main\npassword=LEAK2\n");wc::CaptureOptions o;o.root=x.p;auto text=wc::serialize_snapshot(wc::capture(o));check(text.find("TOPSECRET")==std::string::npos&&text.find("LEAK2")==std::string::npos,"credentials");check(text.find("alice") == std::string::npos,"username");}});
 t.push_back({"default privacy sentinels",[]{Tmp x;base(x.p);put(x.p/"etc/hostname","HOST_SENTINEL");put(x.p/"etc/machine-id","MACHINE_ID_SENTINEL");put(x.p/"home/USER_SENTINEL/file","HOME_SENTINEL");put(x.p/"sys/class/net/eth0/address","aa:bb:cc:dd:ee:ff");wc::CaptureOptions o;o.root=x.p;auto text=wc::serialize_snapshot(wc::capture(o));for(auto s:{"HOST_SENTINEL","MACHINE_ID_SENTINEL","USER_SENTINEL","HOME_SENTINEL","aa:bb:cc:dd:ee:ff"})check(text.find(s)==std::string::npos,std::string("leak ")+s);}});
 t.push_back({"repository deterministic order",[]{Tmp x;base(x.p);put(x.p/"etc/apt/sources.list.d/z.list","deb https://z.test stable main\n");put(x.p/"etc/apt/sources.list.d/a.list","deb https://a.test stable main\n");wc::CaptureOptions o;o.root=x.p;auto a=wc::capture(o),b=wc::capture(o);a.captured_at=b.captured_at;check(wc::serialize_snapshot(a)==wc::serialize_snapshot(b),"collector deterministic");}});
 t.push_back({"terminal sanitization",[]{check(wc::sanitize_terminal("ok\x1b[31m") == "ok?[31m","terminal");}});
 t.push_back({"valid JSON diff",[]{auto d=wc::compare(one("x"),one("x"));auto text=wc::format_diff(d,wc::Format::Json);check(wc::Json::parse(text).is_object(),"json output");}});
 t.push_back({"SHA-256 known vector",[]{Tmp x;put(x.p/"f","abc");std::uint64_t n=0;check(wc::sha256_file_nofollow(x.p/"f",100,n)=="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"&&n==3,"sha256");}});
 t.push_back({"atomic no overwrite",[]{Tmp x;auto p=x.p/"out";wc::atomic_write_private(p,"x");struct stat st{};check(stat(p.c_str(),&st)==0&&(st.st_mode&0777)==0600,"mode");throws([&]{wc::atomic_write_private(p,"y");});}});
 t.push_back({"atomic failure FD cleanup",[]{Tmp x;const auto before=open_fd_count();for(int i=0;i<20;++i)throws([&]{wc::atomic_write_private(x.p/"missing"/"out","x");});check(open_fd_count()==before,"atomic failure leaked descriptor");}});
 t.push_back({"atomic symlink refusal",[]{Tmp x;put(x.p/"target","old");fs::create_symlink(x.p/"target",x.p/"out");throws([&]{wc::atomic_write_private(x.p/"out","new");});check(wc::read_file_bounded(x.p/"target",16)=="old","symlink target changed");}});
 t.push_back({"command success FD cleanup",[]{const auto before=open_fd_count();for(int i=0;i<20;++i){auto r=wc::run_command("/bin/echo",{"ok"},1000,1024);check(r.exit_code==0&&r.out=="ok\n"&&!r.timed_out,"echo result");}check(open_fd_count()==before,"command success leaked descriptor");}});
 t.push_back({"command exec failure cleanup",[]{const auto before=open_fd_count();auto r=wc::run_command("/definitely/not/a/program",{},1000,1024);check(r.exit_code==127&&!r.timed_out,"exec failure result");check(open_fd_count()==before,"exec failure leaked descriptor");}});
 t.push_back({"command timeout cleanup",[]{const auto before=open_fd_count();auto r=wc::run_command("/bin/sleep",{"1"},10,1024);check(r.exit_code==124&&r.timed_out,"timeout result");check(open_fd_count()==before,"timeout leaked descriptor");}});
 t.push_back({"command output limit cleanup",[]{const auto before=open_fd_count();auto r=wc::run_command("/usr/bin/yes",{},1000,64);check(r.exit_code==124&&r.timed_out&&r.out.size()<=64,"output limit result");check(open_fd_count()==before,"output limit leaked descriptor");}});
 t.push_back({"stable repeated comparison",[]{auto a=one("x"),b=a;b.categories["x"].entries["k"]=wc::Json("v");check(wc::format_diff(wc::compare(a,b),wc::Format::Json)==wc::format_diff(wc::compare(a,b),wc::Format::Json),"stable compare");}});
 std::size_t pass=0;for(auto&x:t){try{x.second();++pass;std::cout<<"PASS "<<x.first<<"\n";}catch(const std::exception&e){std::cerr<<"FAIL "<<x.first<<": "<<e.what()<<"\n";}}std::cout<<pass<<"/"<<t.size()<<" tests passed\n";return pass==t.size()?0:1;}
